(--accent);color:var(--on-accent);border-color:transparent;font-weight:700}\n.btn.danger{color:#B4533A;border-color:#B4533A}\n.btn.grow{flex:1}\n.act{display:flex;gap:8px}\n\n.hero{display:flex;flex-direction:column;justify-content:center;gap:5px}\n.lab{color:var(--muted);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.big{font-size:28px;font-weight:700;line-height:1.1;font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.card[data-size=\"3x6\"] .big,.card[data-size^=\"6\"] .big{font-size:32px}\n.card[data-size=\"6x6\"] .big{font-size:38px}\n.bar{height:8px;border-radius:99px;background:var(--soft);overflow:hidden}\n.bar>i{display:block;height:100%;border-radius:inherit;background:var(--accent)}\n.bar.sm{height:4px}\n.bar.sm>i{background:var(--accent-alt)}\n.hero.over .lab,.hero.over .big{color:#B4533A}\n.hero.over .bar>i{background:#B4533A}\n.sub{display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0;font-size:12px;color:var(--muted)}\n.sp{flex:none;white-space:nowrap}\n.bb{min-width:0;padding:2px 0;border:0;background:transparent;color:var(--accent);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n\n.cats,.recent{display:flex;flex-direction:column;gap:6px}\n.sec{flex:none;color:var(--muted);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.cats>.lst,.recent>.lst{flex:1;min-height:0;overflow:auto}\n.cats>.lst{display:flex;flex-direction:column;gap:7px}\n.cat{flex:none}\n.cat .t{display:flex;justify-content:space-between;gap:8px;margin-bottom:3px}\n.cat .n{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.cat b{flex:none;font-variant-numeric:tabular-nums}\n.empty{padding:10px 0;color:var(--muted);font-size:12px}\n\n.row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:8px;width:100%;padding:7px 2px;border:0;border-bottom:1px solid var(--line);background:transparent;text-align:left}\n.row .d{color:var(--muted);font-size:12px;white-space:nowrap;font-variant-numeric:tabular-nums}\n.row .m{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.row .m em{color:var(--muted);font-style:normal}\n.row .a{white-space:nowrap;font-weight:700;font-variant-numeric:tabular-nums}\n.row.mrow{display:flex;flex-direction:column;align-items:flex-start;gap:1px}\n.row.mrow.sel{background:var(--soft)}\n.row .a2{color:var(--muted);font-size:12px;white-space:nowrap;font-variant-numeric:tabular-nums}\n.recent>.lst{display:flex;flex-direction:column}\n\n.page{flex:1;min-height:0;display:flex;flex-direction:column;gap:8px}\n.page-hd{flex:none;display:flex;align-items:center;gap:8px}\n.ttl{min-width:0;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.page-bd{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:10px;padding-right:2px}\n.page-bd>*{flex:none}\n.page-ft{flex:none;display:flex;flex-wrap:wrap;align-items:center;gap:6px 8px}\n.page-ft .btn{flex:none}\n.page-ft .btn.grow{flex:1}\n.err{flex:1 1 100%;color:#B4533A;font-size:12px}\n.warn{flex:1;min-width:0;color:var(--ink);font-size:12px}\n.sum{font-size:12px;color:var(--muted)}\n.sum.over{color:#B4533A}\n.hint{font-size:12px;color:var(--muted)}\n\n.flds{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.fld.full{grid-column:1/-1}\n.fld>span{color:var(--muted);font-size:12px}\n.inp{width:100%;min-width:0;height:34px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink)}\n.chips{display:flex;flex-wrap:wrap;gap:5px}\n.chip{height:28px;padding:0 10px;border:1px solid var(--line);border-radius:99px;background:var(--panel-paper)}\n.chip.on{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:700}\n";
var CATS=['餐饮','交通','日用','购物','娱乐','学习','医疗','其他'];
var BASE_BUDGET=3000;

function initialize(s){
  s=s||{};
  var ok=typeof s.budget==='number'&&s.budgets&&typeof s.budgets==='object'&&Array.isArray(s.expenses);
  if(ok)return s;
  return Object.assign({},s,{
    budget:typeof s.budget==='number'?s.budget:BASE_BUDGET,
    budgets:s.budgets&&typeof s.budgets==='object'?s.budgets:{},
    expenses:Array.isArray(s.expenses)?s.expenses:[]
  });
}
function r2(n){return Math.round(n*100)/100;}
function fmt(n){
  var neg=n<0,a=Math.abs(r2(n)),t=a.toFixed(2);
  if(/\.00$/.test(t))t=t.slice(0,-3);
  var p=t.split('.');
  p[0]=p[0].replace(/\B(?=(\d{3})+(?!\d))/g,',');
  return (neg?'-':'')+'¥'+p.join('.');
}
function pad2(n){return ('0'+n).slice(-2);}
function mLabel(m){return m.slice(0,4)+'年'+(+m.slice(5,7))+'月';}
function mShift(m,d){
  var y=+m.slice(0,4),k=+m.slice(5,7)-1+d;
  y+=Math.floor(k/12);
  k=((k%12)+12)%12;
  return y+'-'+pad2(k+1);
}
function lastDay(m){return new Date(+m.slice(0,4),+m.slice(5,7),0).getDate();}
function budgetOf(s,m){
  var b=s.budgets||{},k=null;
  Object.keys(b).forEach(function(x){if(x<=m&&(k===null||x>k))k=x;});
  if(k!==null)return b[k];
  return typeof s.budget==='number'?s.budget:BASE_BUDGET;
}
function monthStats(s,m){
  var all=Array.isArray(s.expenses)?s.expenses:[];
  var list=all.filter(function(x){return String(x.date).slice(0,7)===m;}).reverse();
  list.sort(function(a,b){return a.date<b.date?1:(a.date>b.date?-1:0);});
  var by={},total=0;
  list.forEach(function(x){
    by[x.cat]=r2((by[x.cat]||0)+x.amount);
    total=r2(total+x.amount);
  });
  return {list:list,by:by,total:total,budget:budgetOf(s,m)};
}
function monthsOf(s,cur,month){
  var set={};
  set[cur]=1;set[month]=1;
  (Array.isArray(s.expenses)?s.expenses:[]).forEach(function(x){set[String(x.date).slice(0,7)]=1;});
  return Object.keys(set).sort();
}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day,size}=ctx;
  const S=state||{};
  const today=day(),cur=today.slice(0,7);
  const month=ui.month||cur;
  const view=ui.view||'main';
  const info=monthStats(S,month);
  const left=r2(info.budget-info.total),over=left<0;
  const months=monthsOf(S,cur,month);
  const minM=months[0],maxM=months[months.length-1];
  const mn=+month.slice(5,7);

  function go(p){Object.assign(ui,p);redraw();}
  function btn(label,cls,fn){return el('button',{type:'button',class:'btn '+(cls||''),onclick:fn},label);}
  function fail(msg){ui.saving=false;ui.err=msg;redraw();}

  function openForm(x){
    ui.draft=x?{id:x.id,amount:String(x.amount),cat:x.cat,date:x.date,note:x.note||''}
      :{amount:'',cat:ui.lastCat||CATS[0],date:month===cur?today:month+'-'+pad2(lastDay(month)),note:''};
    ui.back=view==='form'?'main':view;
    ui.err='';ui.del=false;ui.saving=false;ui.view='form';
    redraw();
  }
  function openBudget(){
    ui.bdraft={v:String(info.budget)};
    ui.back=view;ui.err='';ui.saving=false;ui.view='budget';
    redraw();
  }

  function nav(){
    return el('div',{class:'nav'},
      el('button',{type:'button',class:'ibtn','aria-label':'上个月',disabled:month<=minM,onclick:()=>go({month:mShift(month,-1)})},'‹'),
      el('button',{type:'button',class:'mlab','aria-label':'查看各月份',onclick:()=>go({view:'months'})},mLabel(month)+' ▾'),
      el('button',{type:'button',class:'ibtn','aria-label':'下个月',disabled:month>=maxM,onclick:()=>go({month:mShift(month,1)})},'›'));
  }

  function hero(){
    const pct=info.budget>0?Math.min(100,Math.max(0,info.total/info.budget*100)):(info.total>0?100:0);
    const lab=over?'⚠ '+(month===cur?'本月':mn+'月')+'已超支':(month===cur?'本月还剩':mn+'月还剩');
    return el('div',{class:'hero'+(over?' over':'')},
      el('div',{class:'lab'},lab),
      el('div',{class:'big'},fmt(Math.abs(left))),
      el('div',{class:'bar','aria-label':'预算已用 '+Math.round(pct)+'%'},el('i',{style:'width:'+pct+'%'})),
      el('div',{class:'sub'},
        el('span',{class:'sp'},'已花 '+fmt(info.total)),
        el('button',{type:'button',class:'bb','aria-label':'修改月预算',onclick:openBudget},'预算 '+fmt(info.budget)+' ✎')));
  }

  function catsEl(){
    const keys=Object.keys(info.by).sort((a,b)=>info.by[b]-info.by[a]);
    const rows=keys.length?keys.map(k=>{
      const v=info.by[k],p=info.total>0?v/info.total*100:0;
      return el('div',{class:'cat'},
        el('div',{class:'t'},el('span',{class:'n'},k+' '+Math.round(p)+'%'),el('b',{},fmt(v))),
        el('div',{class:'bar sm'},el('i',{style:'width:'+p+'%'})));
    }):[el('div',{class:'empty'},'这个月还没有记账')];
    return el('div',{class:'cats'},el('div',{class:'sec'},'各类花费'),el('div',{class:'lst'},...rows));
  }

  function rowEl(x){
    return el('button',{type:'button',class:'row',onclick:()=>openForm(x)},
      el('span',{class:'d'},x.date.slice(5)),
      el('span',{class:'m'},el('b',{},x.cat),...(x.note?[el('em',{},' · '+x.note)]:[])),
      el('span',{class:'a'},fmt(x.amount)));
  }
  function listRows(){
    return info.list.length?info.list.map(rowEl):[el('div',{class:'empty'},'还没有记账，点「记一笔」开始')];
  }
  function recentEl(){
    return el('div',{class:'recent'},
      el('div',{class:'sec'},'账目 · '+info.list.length+' 笔 · 点击可修改'),
      el('div',{class:'lst'},...listRows()));
  }
  function actEl(){
    return el('div',{class:'act'},
      btn('+ 记一笔','pri grow',()=>openForm(null)),
      ...(size==='6x6'?[]:[btn('明细','',()=>go({view:'detail'}))]));
  }
  function mainView(){
    const parts=[el('div',{class:'hd'},nav()),hero()];
    if(size!=='3x3')parts.push(catsEl());
    if(size==='6x6')parts.push(recentEl());
    parts.push(actEl());
    return el('div',{class:'main'},...parts);
  }


  function pageHd(title,fn){
    return el('div',{class:'page-hd'},
      el('button',{type:'button',class:'ibtn','aria-label':'返回',onclick:fn},'‹'),
      el('div',{class:'ttl'},title));
  }
  function toBack(){go({view:ui.back||'main',err:'',del:false});}
  function errEl(){return ui.err?el('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;}
  function foot(...items){
    const e=errEl();
    return el('div',{class:'page-ft'},...(e?[e]:[]),...items);
  }
  function saveTo(fn,patch){
    if(ui.saving)return;
    ui.saving=true;
    commit(fn,Object.assign({},ui,{view:ui.back||'main',draft:null,bdraft:null,err:'',saving:false,del:false},patch||{}))
      .catch(()=>fail('保存失败，请重试'));
  }

  function detailView(){
    const sum='已花 '+fmt(info.total)+' · 预算 '+fmt(info.budget)+' · '+(over?'超支 ':'还剩 ')+fmt(Math.abs(left));
    return el('div',{class:'page'},
      pageHd(mLabel(month)+' 明细',()=>go({view:'main'})),
      el('div',{class:'page-bd'},
        el('div',{class:'sum'+(over?' over':'')},sum),
        catsEl(),
        el('div',{class:'sec'},'账目 · '+info.list.length+' 笔 · 点击可修改'),
        el('div',{class:'lst'},...listRows())),
      foot(btn('+ 记一笔','pri grow',()=>openForm(null))));
  }

  function formView(){
    const d=ui.draft,editing=!!d.id;
    const amt=el('input',{class:'inp',type:'number',inputmode:'decimal',step:'any',min:'0',value:d.amount,placeholder:'0.00','aria-label':'金额（元）',oninput:e=>{d.amount=e.target.value;}});
    const chips=CATS.map((c,i)=>el('button',{type:'button',class:'chip'+(d.cat===c?' on':''),'aria-pressed':d.cat===c?'true':'false',onclick:()=>{
      d.cat=c;ui.lastCat=c;
      chips.forEach((b,j)=>{b.classList.toggle('on',i===j);b.setAttribute('aria-pressed',i===j?'true':'false');});
    }},c));
    const dt=el('input',{class:'inp',type:'date',value:d.date,'aria-label':'日期',oninput:e=>{d.date=e.target.value;},onchange:e=>{d.date=e.target.value;}});
    const nt=el('input',{class:'inp',type:'text',value:d.note,maxlength:'40',placeholder:'可不填，如：午饭','aria-label':'备注',oninput:e=>{d.note=e.target.value;}});
    const save=()=>{
      const n=r2(Number(d.amount));
      let err='';
      if(d.amount===''||!isFinite(n)||!(n>0))err='请输入大于 0 的金额';
      else if(n>9999999)err='金额过大，请检查';
      else if(!d.cat)err='请选择类别';
      else if(!/^\d{4}-\d{2}-\d{2}$/.test(d.date||''))err='请选择日期';
      if(err){ui.err=err;redraw();return;}
      const rec={id:d.id||uid(),amount:n,cat:d.cat,date:d.date,note:(d.note||'').trim()};
      saveTo(s=>{
        const list=Array.isArray(s.expenses)?s.expenses:[];
        const has=list.some(x=>x.id===rec.id);
        return Object.assign({},s,{expenses:has?list.map(x=>x.id===rec.id?rec:x):list.concat([rec])});
      },{month:rec.date.slice(0,7)});
    };
    const del=()=>saveTo(s=>Object.assign({},s,{expenses:(Array.isArray(s.expenses)?s.expenses:[]).filter(x=>x.id!==d.id)}));
    const ft=ui.del
      ?foot(el('span',{class:'warn'},'确定删除这笔？'),btn('确认删除','danger',del),btn('取消','',()=>go({del:false,err:''})))
      :foot(btn(editing?'保存修改':'保存','pri grow',save),...(editing?[btn('删除','danger',()=>go({del:true,err:''}))]:[]));
    return el('div',{class:'page'},
      pageHd(editing?'修改这笔':'记一笔',toBack),
      el('div',{class:'page-bd'},
        el('div',{class:'flds'},
          el('label',{class:'fld'},el('span',{},'金额（元）'),amt),
          el('label',{class:'fld'},el('span',{},'日期'),dt),
          el('div',{class:'fld full'},el('span',{},'类别'),el('div',{class:'chips'},...chips)),
          el('label',{class:'fld full'},el('span',{},'备注（可选）'),nt))),
      ft);
  }

  function budgetView(){
    const b=ui.bdraft;
    const inp=el('input',{class:'inp',type:'number',inputmode:'decimal',step:'any',min:'0',value:b.v,'aria-label':'月预算（元）',oninput:e=>{b.v=e.target.value;}});
    const save=()=>{
      const n=r2(Number(b.v));
      if(b.v===''||!isFinite(n)||!(n>0)){ui.err='请输入大于 0 的预算';redraw();return;}
      saveTo(s=>Object.assign({},s,{budgets:Object.assign({},s.budgets||{},{[month]:n})}));
    };
    return el('div',{class:'page'},
      pageHd('月预算',toBack),
      el('div',{class:'page-bd'},
        el('label',{class:'fld'},el('span',{},'每月预算（元）'),inp),
        el('div',{class:'hint'},'从 '+mLabel(month)+' 起生效，之后的月份沿用；更早月份的预算和账目不变。')),
      foot(btn('保存预算','pri grow',save),btn('取消','',toBack)));
  }

  function monthsView(){
    const rows=months.slice().reverse().map(m=>{
      const i=monthStats(S,m),l=r2(i.budget-i.total);
      return el('button',{type:'button',class:'row mrow'+(m===month?' sel':''),onclick:()=>go({month:m,view:'main'})},
        el('span',{class:'m'},el('b',{},mLabel(m)),el('em',{},' · '+i.list.length+' 笔')),
        el('span',{class:'a2'},'已花 '+fmt(i.total)+(l<0?' · 超支 ':' · 还剩 ')+fmt(Math.abs(l))));
    });
    return el('div',{class:'page'},
      pageHd('各月账目',()=>go({view:'main'})),
      el('div',{class:'page-bd'},el('div',{class:'lst'},...rows)));
  }

  function render(){
    let v=view;
    if((v==='form'&&!ui.draft)||(v==='budget'&&!ui.bdraft))v='main';
    const fns={main:mainView,detail:detailView,form:formView,budget:budgetView,months:monthsView};
    root.appendChild((fns[v]||mainView)());
  }
  render();
}

